// lib/calculos.mjs — os cálculos da venda: subtotal de cada item e total do carrinho.

// Subtotal = preço VEZES quantidade. O preço e a quantidade podem chegar
// como TEXTO (vieram de um formulário): converta com Number() antes de
// multiplicar. Item sem preco ou sem quantidade lança erro.
export function calcularSubtotal(item) {
  if (item.preco === undefined || item.quantidade === undefined) {
    throw new Error('item sem preco ou quantidade');
  }
  return Number(item.preco) * Number(item.quantidade);
}

// Total do carrinho = soma dos subtotais. Lista vazia devolve 0.
export function calcularTotal(itens) {
  if (!Array.isArray(itens)) {
    throw new Error('itens precisa ser uma lista');
  }
  return itens.reduce((soma, item) => soma + calcularSubtotal(item), 0);
}

