// lib/descontos.mjs — os cupons de desconto da loja.

// Cupom aplica um fator sobre o total. Cupom desconhecido (ou ausente) NÃO
// desconta: devolve o total como está.
const CUPONS = {
  TECH10: 0.9, // 10% de desconto
  TECH20: 0.8, // 20% de desconto
};

export function aplicarCupom(total, cupom) {
  if (typeof total !== 'number') {
    throw new Error('total invalido');
  }
  const fator = CUPONS[cupom];
  if (fator === undefined) {
    return total;
  }
  return total * fator;
}

